#!/usr/bin/env bash
# Reproduces the parser spike of ADR 1000: the Go grammar generated by ANTLR 4 and by the PEG
# generator of the spike, both run against the hand-written Go parser on the Go distribution's src/.
# Needs: java, python3, go (for GOROOT), the .NET 10 SDK, network access for the ANTLR jar and the
# grammars-v4 files. Writes everything into a fresh temporary directory.
set -euo pipefail

here="$(cd "$(dirname "$0")" && pwd)"
repo="$(cd "$here/../../../.." && pwd)"
work="$(mktemp -d)"
corpus="${1:-$(go env GOROOT)/src}"
rounds="${2:-3}"
grammars="https://raw.githubusercontent.com/antlr/grammars-v4/5ed230f528feb62b45e17880d9fb0af8ca2ef7c9/golang"

dotnet build "$repo/Polypiler.Core.Frontends.Go" -c Release
go_dll="$repo/Polypiler.Core.Frontends.Go/bin/Release/net10.0/Polypiler.Core.Frontends.Go.dll"

project() { # <dir> <extra item group>
  cat > "$1/Spike.csproj" <<EOF
<Project Sdk="Microsoft.NET.Sdk">
  <PropertyGroup>
    <OutputType>Exe</OutputType>
    <TargetFramework>net10.0</TargetFramework>
    <ImplicitUsings>disable</ImplicitUsings>
    <NoWarn>\$(NoWarn);CS3021;CS0108;CS8981;CS1591;CS8618</NoWarn>
  </PropertyGroup>
  <ItemGroup>
    <Reference Include="Polypiler.Core.Frontends.Go"><HintPath>$go_dll</HintPath></Reference>
    $2
  </ItemGroup>
</Project>
EOF
}

# ANTLR 4.13.2 with the grammars-v4 Go grammar (BSD).
mkdir -p "$work/antlr/gen"
curl -sSLo "$work/antlr.jar" https://repo1.maven.org/maven2/org/antlr/antlr4/4.13.2/antlr4-4.13.2-complete.jar
for f in GoLexer.g4 GoParser.g4 CSharp/GoParserBase.cs; do curl -sSLo "$work/antlr/$(basename "$f")" "$grammars/$f"; done
(cd "$work/antlr" && java -jar "$work/antlr.jar" -Dlanguage=CSharp -no-listener -o gen GoLexer.g4 GoParser.g4)
mv "$work/antlr/GoParserBase.cs" "$work/antlr/gen/"
cp "$here/AntlrHarness.cs" "$work/antlr/Program.cs"
project "$work/antlr" '<PackageReference Include="Antlr4.Runtime.Standard" Version="4.13.1" />'
sed -i 's|<ImplicitUsings>|<Nullable>disable</Nullable><ImplicitUsings>|' "$work/antlr/Spike.csproj"
dotnet build "$work/antlr" -c Release
dotnet "$work/antlr/bin/Release/net10.0/Spike.dll" "$corpus" | tee "$work/antlr-output.txt"

# The PEG generator of the spike over the repository's own Go scanner.
mkdir -p "$work/peg"
cp "$repo/Polypiler.Core.Frontends.Go/Syntax/GoScanner.cs" "$repo/Polypiler.Core.Frontends.Go/Syntax/GoToken.cs" "$work/peg/"
cp "$here/GoPegParser.Runtime.cs" "$work/peg/"
cp "$here/PegHarness.cs" "$work/peg/Program.cs"
python3 -I "$here/pgen.py" "$here/go.pgram" "$work/peg/GoPegParser.g.cs"
project "$work/peg" ''
sed -i 's|<ImplicitUsings>|<Nullable>enable</Nullable><ImplicitUsings>|' "$work/peg/Spike.csproj"
dotnet build "$work/peg" -c Release
dotnet "$work/peg/bin/Release/net10.0/Spike.dll" "$corpus" "$rounds" | tee "$work/peg-output.txt"

echo "outputs in $work"
